import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"智能爆炸报告中文全译","description":"","frontmatter":{"title":"智能爆炸报告中文全译"},"headers":[],"relativePath":"notes/intelligence-explosion-zh.md","filePath":"notes/intelligence-explosion-zh.md","lastUpdated":1791194342000}'),i={name:"notes/intelligence-explosion-zh.md"};function n(l,t,d,A,s,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="《如果自动化-ai-研发触发智能爆炸-会发生什么-》中文全译" tabindex="-1">《如果自动化 AI 研发触发智能爆炸，会发生什么？》中文全译 <a class="header-anchor" href="#《如果自动化-ai-研发触发智能爆炸-会发生什么-》中文全译" aria-label="Permalink to &quot;《如果自动化 AI 研发触发智能爆炸，会发生什么？》中文全译&quot;">​</a></h1><blockquote><p>📄 原文：<em>What if automating AI R&amp;D triggers an intelligence explosion?</em>（官方中文版标题译作《当 AI 接管 AI 研发：智能爆炸及其应对措施》） 🏛️ 出自：剑桥大学 <strong>AI 科学与政策项目（Cambridge Programme on AI Science &amp; Policy, CASP）</strong> · Frontier AI Working Paper Series <strong>No. 2/2026</strong> · 2026 年 9 月 👥 作者（22 位，按原文署名顺序）：Alan Chan*（GovAI）、Christoph Winter（剑桥 CASP；Institute for Law &amp; AI）、Andrew Barto（马萨诸塞大学阿默斯特分校）、Jakub Pachocki（OpenAI）、Geoffrey Hinton（多伦多大学；Vector Institute）、Eric Horvitz（微软）、Yoshua Bengio（Mila；蒙特利尔大学；LawZero）、Dawn Song（UC 伯克利）、Jack Clark（Anthropic）、Hilary Greaves（牛津大学）、Anton Korinek（弗吉尼亚大学；Anthropic）、Samuel Hammond（美国创新基金会）、Thore Graepel（伦敦大学学院）、Ben Bariach（牛津大学）、Philip H. S. Torr（牛津大学）、Sheila A. McIlraith（多伦多大学；Vector Institute）、Jeff Clune（不列颠哥伦比亚大学；Vector Institute）、Sam Manning（GovAI；美国创新基金会）、Girish Sastry（Guidelight）、Tom Davidson（Forethought）、Daniel Eth（AI 政策研究所）、Sören Mindermann*（剑桥 CASP）。完整作者—机构对照表见<a href="#作者与机构">文末</a>。 🔗 报告页面：<a href="https://casp.ac/reports/intelligence-explosion" target="_blank" rel="noreferrer">https://casp.ac/reports/intelligence-explosion</a> ｜ <a href="https://casp.ac/__l5e/assets-v1/5efd4b41-deb5-4513-a0a3-b4f82d2b79ea/intelligence-explosion.pdf" target="_blank" rel="noreferrer">原文 PDF</a> ｜ <a href="https://casp.ac/__l5e/assets-v1/026ee81c-773c-4811-9c97-f7cf367ee7b0/intelligence-explosion-summary.pdf" target="_blank" rel="noreferrer">执行摘要 PDF</a> ｜ <a href="https://casp.ac/__l5e/assets-v1/de5ca495-dc72-4635-ab60-438a1e52692c/intelligence-explosion-chinese.pdf" target="_blank" rel="noreferrer">官方中文版 PDF</a>（译者：Zilan Qian） 📥 本站存档：<a href="/papers/intelligence-explosion.pdf">原文 PDF 备份</a>（存于 2026-10-05） ⚖️ 原文版权归 CASP 与作者所有。本页为<strong>个人学习用途的中文全译</strong>（非官方翻译），核心术语对齐官方中文版；引用请以官方版本为准。 🤖 全译由 AI（ZCode）辅助完成、经人工校订整理于 2026-10-05；参考文献从略（见原文，共 92 条）。原文补充材料中三处公式的 ω/ε 疑似排版互换，本译按论文自身定义与数值结果还原为自洽形式，并加<a href="#补充材料">译注</a>说明。</p></blockquote><h2 id="作者与机构" tabindex="-1">作者与机构 <a class="header-anchor" href="#作者与机构" aria-label="Permalink to &quot;作者与机构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>作者</th><th>机构</th></tr></thead><tbody><tr><td>1</td><td>Alan Chan*</td><td>GovAI</td></tr><tr><td>2</td><td>Christoph Winter</td><td>剑桥大学 AI 科学与政策项目（CASP）；法律与人工智能研究所（Institute for Law &amp; AI）</td></tr><tr><td>3</td><td>Andrew Barto</td><td>马萨诸塞大学阿默斯特分校</td></tr><tr><td>4</td><td>Jakub Pachocki</td><td>OpenAI</td></tr><tr><td>5</td><td>Geoffrey Hinton</td><td>多伦多大学；Vector Institute</td></tr><tr><td>6</td><td>Eric Horvitz</td><td>微软</td></tr><tr><td>7</td><td>Yoshua Bengio</td><td>Mila（魁北克人工智能研究所）；蒙特利尔大学；LawZero</td></tr><tr><td>8</td><td>Dawn Song</td><td>加利福尼亚大学伯克利分校</td></tr><tr><td>9</td><td>Jack Clark</td><td>Anthropic</td></tr><tr><td>10</td><td>Hilary Greaves</td><td>牛津大学</td></tr><tr><td>11</td><td>Anton Korinek</td><td>弗吉尼亚大学；Anthropic</td></tr><tr><td>12</td><td>Samuel Hammond</td><td>美国创新基金会（Foundation for American Innovation）</td></tr><tr><td>13</td><td>Thore Graepel</td><td>伦敦大学学院（UCL）</td></tr><tr><td>14</td><td>Ben Bariach</td><td>牛津大学</td></tr><tr><td>15</td><td>Philip H. S. Torr</td><td>牛津大学</td></tr><tr><td>16</td><td>Sheila A. McIlraith</td><td>多伦多大学；Vector Institute</td></tr><tr><td>17</td><td>Jeff Clune</td><td>不列颠哥伦比亚大学；Vector Institute</td></tr><tr><td>18</td><td>Sam Manning</td><td>GovAI；美国创新基金会</td></tr><tr><td>19</td><td>Girish Sastry</td><td>Guidelight</td></tr><tr><td>20</td><td>Tom Davidson</td><td>Forethought</td></tr><tr><td>21</td><td>Daniel Eth</td><td>AI 政策研究所（AI Policy Institute）</td></tr><tr><td>22</td><td>Sören Mindermann*</td><td>剑桥大学 AI 科学与政策项目（CASP）</td></tr></tbody></table><blockquote><p>* 通讯作者：alan.chan@governance.ai；soren.mindermann@casp.ac。本文观点仅代表作者本人，不一定代表其所属机构的立场。</p></blockquote><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>与仅仅一年前相比，如今在构建 AI 的公司内部，大部分代码已由 AI 系统编写。随着 AI 研发（R&amp;D）流程中越来越多的环节被自动化，AI 进步是否会在一场&quot;智能爆炸&quot;（intelligence explosion）中急剧加速——把原本需要数年的进展压缩到数月甚至更短？初步证据表明这有可能。在本报告中，我们评估了这些证据，分析了智能爆炸的潜在影响，并提出政策应对。AI 系统正朝着在几年内自动化大部分 AI 研发工作、甚至全部工作的方向前进。如果这引发智能爆炸，它可能大幅提前 AI 收益的到来，但也构成极端风险：能力增长可能加速到远超社会所能跟上的程度，人类可能失去对超人类 AI 系统的控制，国家之间与国家内部、企业之间、政府各部门之间的权力制衡也可能遭到严重削弱。尽管这些可能性仍存在很大不确定性，但事关重大，值得严肃地进一步关注。政策制定者应紧急行动：更多掌握 AI 研发自动化的进展，找到引导和约束智能爆炸的方法，并让社会做好准备以适应智能爆炸的影响。</p><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>计算机科学家早就提出过这样的猜想：AI 系统终有一天会设计出越来越好的后继者，产出在数量、速度与能力上都迅速超越人类的系统 [1–3]。今天，前沿 AI 公司正致力于自动化 AI 研发 [4, 5]，其投入的资本占美国 GDP 的比重已超过曼哈顿计划与阿波罗计划的总和 [6]。如果它们成功了，会发生什么？</p><p>本报告的核心关切是<strong>智能爆炸</strong>的可能性：AI 驱动的 AI 进步的急剧加速，把原本需要数年才能取得的进展压缩到数月或更短。相较于过去几年快速但大体平稳的进步，这种加速将是一次质的转变。</p><p>智能爆炸可能源自 AI 对硬件和/或软件进步的贡献。<strong>硬件进步</strong>提升用于开发和运行 AI 系统的计算硬件（算力）的质量与数量。<strong>软件进步</strong>则改进 AI 研发中使用的数据、算法、代码与流程，包括在现有硬件上更高效的训练与推理 [7–9]、更好的科研管理与运营、更优质的合成数据与训练环境 [10, 11]，以及 AI 的新范式 [12, 13]。近期而言，软件进步尤其值得关注，原因有二。其一，AI 系统在 AI 研发上的能力似乎正在快速提升，这使它们更擅长产出此类进步。其二，软件进步能形成快速反馈回路：改进后的 AI 系统几乎可以立即重新投入研发流程，而硬件改进通常要依赖长达数年的制造与建设周期。</p><blockquote><p><strong>图 1.</strong> 政策制定者应紧急行动：(1) 掌握前沿 AI 公司内部 AI 研发自动化的情况；(2) 找到引导和约束智能爆炸的方法；(3) 准备适应智能爆炸的影响。</p></blockquote><p>因此，本文聚焦于<strong>软件驱动的智能爆炸</strong>的可能性：AI 研发的自动化仅凭软件进步就能驱动智能爆炸 [14]。</p><p>初步证据表明，软件驱动的智能爆炸是可能的。它一旦发生，可能成为史上影响最深远的技术发展：AI 系统可能在大多数领域迅速超越人类专家，并从根本上加速技术进步。鉴于利害之重与行动窗口之窄，我们认为，为智能爆炸做好准备应当成为紧迫的优先事项，包括在政府最高领导层层面。</p><h2 id="ai-正在快速自动化-ai-研发" tabindex="-1">AI 正在快速自动化 AI 研发 <a class="header-anchor" href="#ai-正在快速自动化-ai-研发" aria-label="Permalink to &quot;AI 正在快速自动化 AI 研发&quot;">​</a></h2><p>AI 系统如今或协助、或自主完成 AI 研发流程的主要环节。与仅仅一年前相比，头部 AI 公司的研发人员已把核心研发任务委托给 AI 系统团队，有些人甚至把全部编码工作都委托出去。Anthropic 报告称，2025 年 1 月至 2026 年 5 月间，AI 系统在获批代码中的占比从个位数低段升至 80% 以上 [5]；2026 年 3 月至 8 月间，仅需高层级人类监督即可自主完成的研发工作占比从 1% 升至 26% [15]。OpenAI 报告称，&quot;从技术团队到非技术团队，AI 辅助实际上已用于公司的所有部门，执行代码的智能体被用于训练、评估和保障未来的模型&quot;；谷歌则报告称，&quot;几乎所有涉及编写代码或配置、技术设计、研究构想的工作都不同程度地使用了 AI，程度因任务而异&quot; [16]。</p><p>如今最先进的 AI 系统能够完成需要人类专家数小时到数天的 AI 研发任务，而在 2023 年它们还只能完成以秒计的任务 [17–19]。AI 系统有时还会胜过人类专家：它们曾自主为一个 AI 安全研究问题产出更好的解决方案 [20]；在某些情境下，它们比人类更准确地预测哪些研究想法会成功 [21]、哪些下一步值得推进 [5]。在一个早期概念验证中，一条自动化的 AI 研究流水线生成研究想法、运行实验并写出论文，该论文在一个顶级机器学习会议下属研讨会通过了同行评审 [22]。¹</p><p>今天的 AI 系统仍有许多弱点。它们有时不服从指令、在任务中作弊、歪曲自己的工作成果，有些任务则完全无法完成，需要人工介入 [23–25]。例如，GPT-6 无法完成 OpenAI 的部分研究调试任务，而经验丰富的人类研究人员可以完成（尽管需要数小时或数天）[25]。基准测试上的成功也可能无法转化为现实世界中的生产力提升 [26]。尽管如此，AI 系统在 AI 研发上的能力仍在快速进步。</p><p>AI 研发很可能先于大多数其他工作被自动化：它本质上是一个数字领域，拥有众多清晰的成败衡量标准；自动化 AI 研发将为 AI 行业带来重大竞争优势；而且 AI 公司掌握着关于自身工作流程的无与伦比的数据与专业知识。对近期趋势的一些初步外推表明，到 2028 年年中，耗时数月的 AI 研发项目将被自动化。² 总体而言，我们应当预期未来几年 AI 研发自动化将大幅推进，甚至应认真对待在此时间框架内实现完全自动化的可能。</p><h2 id="自动化-ai-研发可能触发智能爆炸" tabindex="-1">自动化 AI 研发可能触发智能爆炸 <a class="header-anchor" href="#自动化-ai-研发可能触发智能爆炸" aria-label="Permalink to &quot;自动化 AI 研发可能触发智能爆炸&quot;">​</a></h2><p>软件驱动智能爆炸的机制包含两个部分：(1) 随着 AI 系统在 AI 研发上变得更好更快，它们扩大了<strong>有效的研发劳动力</strong>；(2) 这支劳动力又造出更好的 AI 系统，在递归反馈回路中进一步扩大这支劳动力。尽管现有证据是初步的、有时相互矛盾，但它表明这一机制有可能从根本上加速 AI 进步，克服收益递减、难以自动化的任务等阻力。</p><blockquote><p><strong>图 2.</strong> 软件驱动智能爆炸的机制包含两个部分：(1) 随着 AI 系统在 AI 研发上变得更好更快，它们扩大了有效的研发劳动力；(2) 这支劳动力又造出更好的 AI 系统，在递归反馈回路中进一步扩大这支劳动力。</p></blockquote><h3 id="机制与阻力" tabindex="-1">机制与阻力 <a class="header-anchor" href="#机制与阻力" aria-label="Permalink to &quot;机制与阻力&quot;">​</a></h3><p>每一代新的 AI 系统都会以比人类更快更好的表现完成越来越多的研发任务，实际上相当于造就一支<strong>更大、更聪明、更快的自动化研发队伍</strong>。一旦 AI 系统在运行成本与当今系统相当的前提下达到专家级 AI 研发能力，今天一家前沿开发商所拥有的算力，就足以支撑一支相当于至少数百万顶尖人类研究者的 AI 队伍（见<a href="#补充材料">补充材料</a>），远超前沿公司目前雇用的数千名研究者。由此带来的加速在幅度与持续期上仍不确定，值得进一步研究。不过，要理解这种加速为何可能相当可观，不妨反过来看：如果今天的人类研究者数量或速度缩减十倍，AI 进步很可能显著放缓。</p><p>AI 系统还帮助构建能力更强、效率更高的后继者，进一步扩大自动化研发队伍，并形成一个能够维持并逐级放大加速效果的反馈回路。过去的技术也有反馈回路：例如，更好的计算机芯片催生更好的芯片设计工具。软件驱动智能爆炸的特别之处可能在于 AI 系统对下一代系统的贡献之大：随着 AI 在越来越多的研发任务上替代人类，每一项软件进步都会加速研发流程中越来越大的部分。在完全自动化的情况下，即使按当前的效率提升速度，自动化研发队伍也会在数月到数年内增长 100 倍³，而美国研究者群体的相应扩张花了七十年 [27]。</p><p>至少有四种阻力在对抗这些动态。<strong>第一种是收益递减</strong>：在计算机硬件、农业、药物开发等科学领域中，随着&quot;低垂的果实&quot;被摘尽，维持同样的进步速度所需的研发劳动力大幅增加 [27]。新增研究者自身也面临收益递减，因为他们可能彼此重复劳动，或难以并行推进高价值研发。<strong>第二</strong>，研发依赖算力来运行实验、依赖数据来训练，算力或数据增长的限制可能拖慢软件进步。<strong>第三</strong>，难以自动化的任务可能成为进步的瓶颈。<strong>第四</strong>，一些研发流程本身耗时：例如，即使各代模型之间的能力差距不断扩大，漫长的训练周期也可能限制进步速度。</p><h3 id="证据" tabindex="-1">证据 <a class="header-anchor" href="#证据" aria-label="Permalink to &quot;证据&quot;">​</a></h3><p>初步证据表明，自动化驱动的动态有可能克服这些阻力，尽管证据并不一致，且在某些情况下是间接的。</p><p><strong>收益递减。</strong> 证据表明，收益递减不会阻止智能爆炸，不过这一结论依赖有限的数据和风格化的建模假设。文献中的主要分析关注的是：在 AI 研发完全自动化之后，有效研发劳动力的增长能否快到足以压过收益递减并加速进步。这种平衡由一个称为**&quot;研究投入回报&quot;**（returns to research effort）的量来刻画，记作 $r$。⁴ 当 $r&lt;1$ 时，收益递减占主导，AI 进步随时间衰减；当 $r=1$ 时，两种力量恰好抵消，进步维持原有速率；当 $r&gt;1$ 时，研发劳动力的增长胜出，只要这一条件持续成立，进步就会加速。⁵ Ho 与 Whitfill [28] 利用 AI 进步的历史数据，在三个 AI 研究子领域得到 $r$ 的中心估计值介于 1.2 到 1.9 之间。尽管不确定性相当大，⁶ 这些结果意味着完全自动化后的急剧加速：如果 $r$ 维持在这些水平且没有其他瓶颈出现，AI 进步的速度将在约 1.5 年内提高十倍，届时以今天速度计的一年进步量只需约五周。该分析及关于 $r$ 值不确定性的进一步讨论见<a href="#补充材料">补充材料</a>。</p><p><strong>算力。</strong> 关于算力是否会成为软件驱动智能爆炸的瓶颈，证据并不一致。寻找并验证软件进步需要用算力来运行研发实验。有限的现有数据表明，如果随着前沿训练规模的增长，这类实验所需算力按比例增加，那么软件驱动的智能爆炸就不可能发生 [29]。⁷ 遗憾的是，实验算力需求是否以这种方式增长尚不清楚。一方面，低算力实验对于&quot;在越来越大的前沿规模上什么有效&quot;可能所知甚少。另一方面，从极小规模进行外推如今已经可行 [30, 31]，而且通过更多研发，有望找到更好的外推方法。我们需要更多数据来解决这个问题。</p><p><strong>数据。</strong> 数据可能成为进步的瓶颈，但约束程度因领域而异。历史上，AI 进步严重依赖互联网数据和专家示范。但互联网数据的供给增速预计将放缓，到 2028 年之后甚至难以支撑当前的进步速度 [32]；而人类可能难以替超人类 AI 系统生成有用的示范。为了克服这些限制，数学、编程等领域较新的进展依赖合成数据和快速、可验证的反馈：模型生成自己的尝试，并从尝试是否成功中学习 [12]。关键问题是这种方法能推广到多广的范围。对 AI 研发而言，AI 智能体可以快速测试改动、观察结果、并识别哪些改动加速了自身的进步。在其他领域（如生物学），进步可能不得不更多依赖更慢、噪声更大或成本更高的现实世界反馈。</p><p><strong>难以自动化的任务。</strong> 间接证据表明，只要自动化推进得足够快，难以自动化的任务未必会阻止智能爆炸。Davidson 等人 [33] 在同时考虑软件与硬件的设定中发现，尽管存在自动化瓶颈，只要两个领域的研发自动化都足够快，原则上仍可能触发智能爆炸。⁸ 然而，对于哪些任务可能仍然难以自动化、它们会在多大程度上限制进步，我们还缺乏实证数据。</p><p><strong>耗时流程。</strong> 关于耗时流程在多大程度上可能成为进步的瓶颈，我们缺乏直接证据。最重要的这类流程似乎是训练运行（training runs），目前一次可能需要 3 个月或更久 [34]。潜在的变通办法是存在的，例如通过后训练改进反复提升同一个模型 [35]。此外，训练效率的进步 [36] 将使系统能以更少的训练达到给定的能力水平。但这些方法能走多远尚不清楚。⁹</p><p>总体而言，存在一条与现有证据相容的、通向软件驱动智能爆炸的连贯路径。AI 研发自动化带来的生产力增益尚未达到触发智能爆炸所需的阈值，但更新一代系统的增益很可能正在逼近这一阈值 [37]。¹⁰ AI 研发自动化的快速推进表明，这一差距将继续缩小。鉴于下文讨论的重大利害，智能爆炸的可能性值得严肃的进一步关注。</p><h2 id="社会影响" tabindex="-1">社会影响 <a class="header-anchor" href="#社会影响" aria-label="Permalink to &quot;社会影响&quot;">​</a></h2><p>智能爆炸将导致：(1) 高能力或超人类 AI 系统以极快的速度被开发出来；¹¹ (2) 这些系统很可能被部署用于开发新技术并在现实世界中行动。这可能把当前 AI 进步速度下最终能够实现的收益提前数年或数十年 [38]，包括医疗治愈方法，以及高度可扩展的逐原子制造等潜在的变革性技术 [39]。</p><p>与此同时，智能爆炸可能通过三种方式显著加大先进 AI 的风险。</p><p><strong>能力增长超过社会的引导与适应能力。</strong> 首先，智能爆炸可能大幅提前先进 AI 及 AI 赋能技术的风险，例如生物与网络攻击、劳动力市场紊乱，以及失去对 AI 系统本身的控制 [40, 41]。这将使人类更少有时间规避这些风险，包括通过协调来放慢或放弃开发某些能力或技术。社会的适应时间也会减少，尤其是当 AI 加速威胁的速度快于反制措施所需的速度时。在网络这类以数字为主的领域，风险与缓解措施都可以以 AI 系统的速度推进并彼此保持同步。¹² 但在其他领域，缓解措施比风险更依赖 AI 难以加速的现实世界活动。例如，AI 可以同时加速病毒与疫苗的设计，但病毒能够自我复制与传播，而疫苗必须被制造、分发并逐个接种给接受者 [42]。AI 各项进步到来的先后顺序可能加剧这种失衡，比如具备生物能力的模型先于充分的防滥用保障措施出现。</p><p><strong>监督与控制的丧失。</strong> 其次，AI 研发的自动化可能削弱人类监督，使上述挑战雪上加霜，并大幅增加失去对高能力 AI 系统控制的风险。随着人类越来越少地参与 AI 研发，他们可能同时失去发现和修复问题所需的机会与专业能力。可靠地使用 AI 系统进行监督本身也仍是未解难题 [40]，而且最近几代系统变得更难监督 [25]。监督不足时，目标错位的 AI 系统可能&quot;毒害&quot;后继系统的开发，或绕过遏制措施在其预期环境之外行动。Hugging Face 事件说明了后一种风险：约 1,200 个 OpenAI 内部智能体被安排在彼此隔离的状态下完成网络评估 [43]。这些智能体在超出预定范围行动时，通过一个临时搭建的留言板相互协调，获得了未经授权的互联网访问，入侵 Hugging Face 获取私密信息，并试图篡改自己的对话记录 [43–45]。¹³ 能力更强的系统可能继续在运营方基础设施之外运行，形成持久的、难以遏制的网络，并做出违背人类利益的行为。这种失控可能引发一系列灾难性后果，极端情况下甚至包括人类被边缘化或走向灭绝 [40, 41]。</p><p><strong>权力制衡的侵蚀。</strong> 第三，智能爆炸可能严重侵蚀对权力的制衡。现有的制衡——国家之间与国家内部、企业之间、政府各部门之间——只有在没有任何一方能在思考和执行上大幅超越其他各方时才有效。智能爆炸可能使这些制衡形同虚设。一个国家可能利用智能爆炸把军事研发或行动上的微弱领先转化为决定性优势，例如在网络空间 [46]。这种前景可能刺激对手采取或威胁采取先发制人的行动 [47]。对前沿系统拥有特权访问权和/或秘密访问权的行动者可能威胁现有制度，例如对关键决策者进行定向说服。从更长远的视角看，国家关键职能的自动化可能降低夺取或巩固权力所需的人力支持 [48, 49]。</p><p>这些潜在影响并不确定。AI 系统可能在狭义领域（如网络与数学）早已成为超人类，而在通用能力上远未达到，这给了社会更多反应时间。即使是通用超人类 AI 系统，考虑到运行科学实验、建立特殊材料供应链以及遵守相关法规所需的时间，也未必能显著加速技术进步。AI 系统也可以加速安全研发以及引导风险、适应风险的流程。¹⁴ 最后，能力或技术的扩散 [50] 有助于保全权力制衡，而在防御占优领域的能力提升甚至可能改善稳定性 [51, 52]。尽管如此，严重影响的可能性仍然足够大，值得对下述政策问题给予紧急关注。</p><h2 id="政策启示" tabindex="-1">政策启示 <a class="header-anchor" href="#政策启示" aria-label="Permalink to &quot;政策启示&quot;">​</a></h2><p>AI 研发自动化正在快速推进，AI 进步可能急剧加速，利害攸关。因此我们认为，政策制定者应紧急行动：(1) 掌握公司 AI 研发自动化的情况；(2) 找到引导和约束智能爆炸的方法；(3) 准备适应智能爆炸的影响。由于智能爆炸期间的进展速度会超过常规政策制定流程，准备工作必须提前进行，并随着关于收益与风险的证据出现而启动。</p><h3 id="掌握-ai-研发自动化的进展" tabindex="-1">掌握 AI 研发自动化的进展 <a class="header-anchor" href="#掌握-ai-研发自动化的进展" aria-label="Permalink to &quot;掌握 AI 研发自动化的进展&quot;">​</a></h3><p>政策制定者需要更多关于软件驱动智能爆炸的可能性、起点与后果的数据。这些数据大部分只能在自动化 AI 研发的公司内部获得：相关 AI 系统首先在公司内部使用，大规模自动化可能在缺乏外部可见性的情况下发生。现行的强制报告制度要么未能充分覆盖内部 AI 研发使用场景，要么未规定应报告的指标 [53–57]。尽管一些前沿 AI 公司自愿追踪 AI 研发指标 [5, 15, 18]，但关键指标的覆盖与报告仍不完整、不均衡。</p><p>政策制定者应考虑要求向政府和第三方审计机构标准化报告关键 AI 研发指标与流程，并资助第三方测量能力建设 [58]。报告要求可涵盖与以下方面相关的信息：</p><ul><li><strong>评估软件驱动智能爆炸的可能性</strong>，包括算力、数据、难以自动化的任务以及耗时流程（如训练运行与实验）对 AI 进步构成瓶颈的程度，以及对 AI 研发中研究投入回报的更优估计。估计后者需要关于公司如何在人力、实验用算力与运行 AI 系统执行研发劳动的算力之间分配研发支出的数据 [37]。</li><li><strong>监测智能爆炸的起点</strong>，¹⁵ 包括 AI 研发自动化的程度（如 AI 系统产出的研究贡献占比）与 AI 进步的速度（如算法效率的改进）。</li><li><strong>理解监督与失控风险</strong>，包括决定是否扩大 AI 研发系统内部部署的流程、这些系统在何处以及如何被用于高风险研发决策、如何监督这些系统，以及涉及内部 AI 系统的事件报告 [58]。</li></ul><p>除报告要求之外，政策制定者还应考虑更深入的方式来掌握 AI 研发自动化的情况。例如，可以要求独立第三方（如经认可的民间审计机构或政府评估机构）在内部部署之前评估 AI 系统，或让这类机构进驻某些 AI 公司，对其研发活动进行审计 [59] 或监督 [60]。其他行业中的类似模式包括美国核监管委员会（NRC）[61] 与美国货币监理署（OCC）[62]。</p><p>对于其 AI 系统 (a) 处于 AI 研发能力前沿，或 (b) 超过此类能力的某个有意义阈值的公司，更强的报告与审计要求最为合理。在确定这类阈值时，政策制定者需要权衡重要的取舍。</p><h3 id="引导与约束智能爆炸" tabindex="-1">引导与约束智能爆炸 <a class="header-anchor" href="#引导与约束智能爆炸" aria-label="Permalink to &quot;引导与约束智能爆炸&quot;">​</a></h3><p>智能爆炸将涉及一系列前所未有的快速决策：训练并部署能力越来越强的 AI 系统。政策制定者的总体问题是，公共政策是否以及应如何治理这些决策。我们把它拆分为三个组成部分。</p><p><strong>第一</strong>，政策制定者应找到为自动化 AI 研发的规模化扩张设定节奏并加以约束的方法。他们应考虑：</p><ul><li>为持续部署或持续开发设定前提条件，例如落实充分的安全措施（如对自动化研发管线的稳健监控）、更广泛的相关方意见输入，或对特定时间段内能力提升幅度的限制。</li><li>鉴于竞相争先的竞争压力，准备好核查工具，用于验证对未来可能达成的&quot;为 AI 进步设定节奏&quot;之协议（国内或国际）的遵守情况 [63–65]。</li><li>加强对从事自动化 AI 研发的数据中心的监督，并与数据中心运营商和 AI 公司合作建立事件响应程序，例如制定暂停特定 AI 研发工作负载的预案 [66]。</li><li>要求对自动化 AI 研发系统的某些评估或部署在适当隔离的环境中进行（如物理隔离网络），以防模型权重或敏感研发成果外泄，并遏制试图摆脱人类控制、在现实世界不受约束行动的 AI 系统 [44]。</li></ul><p>政策制定者应在&quot;不受约束的智能爆炸&quot;的风险与&quot;某些权力被滥用、进步被延迟&quot;的可能及代价之间进行权衡。滥用可能性的一个例子是：设计不当的机制可能让政府拖慢除一家受青睐公司之外所有公司的研发。</p><p><strong>第二</strong>，政策制定者应决定是否以及如何引导 AI 开发与部署的方向 [67]。潜在的优先事项包括对齐与安全研发，以及有益的 AI 应用，如借助 AI 发现被忽视疾病的治疗方法。如果现有激励在这些领域不足，政策制定者可以通过税收优惠、算力分配、预先市场承诺和奖金提供支持。</p><p><strong>第三</strong>，各国应降低智能爆炸引发冲突的风险。他们应考虑：</p><ul><li>建立建立信任措施（confidence-building measures），如事件共享 [68]，以及围绕预警指标报告的规范。</li><li>谈判国际协议，防止高能力 AI 系统以破坏稳定的方式发展与使用，并资助可支撑此类协议的核查方法研究 [64, 65]。</li><li>澄清它们是否以及将如何威慑其他行动者进行自动化 AI 研发的规模化扩张，可能与其他国家协作进行 [47, 65]。</li><li>运行战争推演来模拟智能爆炸 [69–71]。</li></ul><h3 id="适应智能爆炸" tabindex="-1">适应智能爆炸 <a class="header-anchor" href="#适应智能爆炸" aria-label="Permalink to &quot;适应智能爆炸&quot;">​</a></h3><p>如果智能爆炸真的发生，适应其影响很可能成为每个世界大国的头等要务。与按部就班的 AI 进步相比，智能爆炸会压缩适应的时间窗口，使提前准备变得更加紧迫。</p><p>一项重要的干预是加快制度响应速度。政策制定者应考虑：</p><ul><li>找到把 AI 系统安全融入政策流程的方法，以增强和支撑政府运作 [72]。</li><li>针对涉及极端 AI 进步的多种情景（包括导致重大劳动力市场冲击、地缘政治不稳定或失控的情景）制定并维护应急预案。</li></ul><p>政策制定者还需要保全权力制衡，防范极端先进 AI 被滥用。法律、制度与物理层面的保障措施可能需要数年才能建立，如果等到这类能力出现之后才开始准备，就为时已晚。因此许多准备工作需要现在就启动。政策制定者应考虑：</p><ul><li>建立保障措施，确保政府对 AI 的使用遵守法律与规范限制，例如采购 AI 工具以强化政府各部门之间的制衡、向公众共享政府 AI 系统的关键信息（如模型规范 [73, 74]），或要求 AI 系统遵守法律 [75]。</li><li>确保公民和公民社会具备发现、记录并质疑 AI 非法或有害使用的能力，例如让他们能够及时获得足以支撑这些活动的 AI 系统。</li><li>帮助建立足以防范恶意非国家行为者滥用的防御，例如资助针对 AI 赋能生物威胁的更优医疗对策 [76]。</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>智能爆炸可能是人类历史上影响最深远的技术发展 [1]：它把数年的进步压缩到数月或更短，威胁人类对 AI 系统的控制，并严重侵蚀国家之间与国家内部、企业之间、政府各部门之间的权力制衡。尽管仍存在很大不确定性，AI 研发的自动化可能很快触发一场智能爆炸。虽然本文聚焦于通向智能爆炸的软件驱动路径，但 AI 驱动的硬件改进¹⁶ 会让智能爆炸更有可能发生。</p><p>与事关重大的利害相比，我们的准备并不充分。政策制定者应有三个优先事项：掌握前沿 AI 公司内部 AI 研发自动化的情况、找到引导和约束智能爆炸的方法、并准备适应其影响。一旦智能爆炸开始，行动窗口可能就此关闭。</p><h2 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h2><p>我们感谢 Anson Ho、Tom Cunningham、Cheryl Wu、Ryan Greenblatt 以及许多 GovAI 工作人员提出的反馈与讨论，它们改进了本文。感谢 Taylor Jones 制作插图，感谢 Zilan Qian 提供本文的中文翻译。</p><h2 id="补充材料" tabindex="-1">补充材料 <a class="header-anchor" href="#补充材料" aria-label="Permalink to &quot;补充材料&quot;">​</a></h2><h3 id="对-ai-队伍有效规模的估计" tabindex="-1">对 AI 队伍有效规模的估计 <a class="header-anchor" href="#对-ai-队伍有效规模的估计" aria-label="Permalink to &quot;对 AI 队伍有效规模的估计&quot;">​</a></h3><p>沿用 Denain 等人 [77] 的方法，我们用&quot;一名开发者每天可生成的 token 数&quot;除以&quot;相当于一名研究者一天工作量所对应的 token 数&quot;来估计有效队伍规模。仅 OpenAI 一家拥有的推理算力（即运行时算力）就足以每天生成约 $10^{13}$ 个 token。为估计每研究者日的 token 数，我们使用模型在一个&quot;人类研究者需要一个工作日（8 小时）&quot;的任务上生成的 token 数。在一项 AI 研发基准中，Wijk 等人 [78] 发现模型在至多 8 小时的运行中平均输出 $5\\cdot 10^{5}$ 个 token，这意味着一支约 $2\\cdot 10^{7}$ 名研究者的有效队伍。考虑到两个方向各约一个数量级的不确定性（每研究者日 $5\\cdot 10^{4}$–$5\\cdot 10^{6}$ 个 token），我们估计有效队伍的量级为 $2\\cdot 10^{6}$–$2\\cdot 10^{8}$。与正文一致，这一估计假设专家级 AI 系统的运行成本与当今系统相当。</p><h3 id="完全自动化下反馈循环的建模" tabindex="-1">完全自动化下反馈循环的建模 <a class="header-anchor" href="#完全自动化下反馈循环的建模" aria-label="Permalink to &quot;完全自动化下反馈循环的建模&quot;">​</a></h3><p>对软件驱动智能爆炸的大多数分析都用某种&quot;软件质量&quot;概念来刻画 AI 进步，记作 $A$。原则上，$A$ 应当整体地度量 AI 进步，同时包括效率改进（新 AI 系统以更少的算力或数据完成与旧系统相同的任务、性能相近）与能力改进（新 AI 系统能完成旧系统无法完成的任务，或达到旧系统无法达到的性能）。令人困扰的是，目前尚不清楚参数 $A$ 应如何在效率改进与能力改进之间（或在两类改进各自内部的不同类型之间）进行权衡。</p><p>撇开这一问题，我们用 $\\mathrm{d}A/\\mathrm{d}t = A^{1-\\varepsilon} E^{\\omega}$ 来建模软件质量的增长，这是创新宏观经济学中常见的函数形式 [27]。为简单起见，我们忽略算力与数据可能带来的瓶颈。这里，$E$ 是有效研发劳动力，$\\omega$ 表示研发劳动力的规模回报，$\\varepsilon$ 表示随时间推移寻找新想法的回报是递增还是递减。</p><blockquote><p><strong>译注</strong>：原文 PDF 中此式及下文两处公式印作 $A^{1-\\omega}E^{\\varepsilon}$、$cA^{\\varepsilon-\\omega+1}$（$c=k^{\\varepsilon}$）、$c\\cdot A^{\\varepsilon-\\omega}$，与论文自身的定义（$\\omega$ 为劳动力规模回报，应作用于 $E$）、正文条件（$\\omega&gt;\\varepsilon$ 时加速）及数值部分（$\\omega-\\varepsilon=0.39$、增长率按 $2^{0.39}$ 放大）均不一致，应为排版时 $\\omega/\\varepsilon$ 互换。本译按自洽形式呈现。</p></blockquote><p>关键问题是 $E$ 如何随 $A$ 增长。在完全自动化的假设下，我们考虑两种情形。第一种情形：软件质量的全部改进都是推理算力效率的提升，即运行某个给定能力水平的 AI 系统所需算力的减少。此时若 $A$ 度量推理效率，则 $E$ 与 $A$ 成正比：推理效率越高，可以运行自动化研究者的数量按比例增加。</p><p>第二种情形：软件质量的全部改进都是由训练算力效率的改进所驱动的能力提升——即在给定算力存量下训练出能力更强的系统，所需训练算力更少。若 $A$ 度量训练算力效率，则 $A$ 的提高带来的是&quot;更强的&quot;系统而非&quot;更多的&quot;系统。如果我们做一个（可能有争议的）假设——研究者的有效数量随能力提升线性扩展——那么 $E$ 同样与 $A$ 成正比。</p><p>两种情形下都有 $E = kA$（$k$ 为某正常数）。代入上式得 $\\mathrm{d}A/\\mathrm{d}t = c,A^{1+\\omega-\\varepsilon}$，其中 $c = k^{\\omega}$。要使增长率 $(1/A),\\mathrm{d}A/\\mathrm{d}t$ 随软件质量提高而增大，需要 $\\omega&gt;\\varepsilon$。定义 $r=\\omega/\\varepsilon$，即得正文讨论的条件 $r&gt;1$。</p><p>按当前对这些参数的估计，进步能多快加速？我们用软件质量的增长率来度量加速：$(1/A),\\mathrm{d}A/\\mathrm{d}t = c\\cdot A^{\\omega-\\varepsilon}$。对 Ho 与 Whitfill [28] 三个子领域的中心估计取平均，得 $\\omega=1.40$、$\\varepsilon=1.01$。由 $\\omega-\\varepsilon=0.39$，$A$ 每翻一倍，增长率乘以 $2^{0.39}\\approx 1.31$，因此每次翻倍所需时间只有上一次的 $(1/2)^{0.39}\\approx 76%$。要使增长率提高十倍，$A$ 需要翻倍 $\\log_2(10)/0.39\\approx 8.5$ 次。第一次翻倍的时长，我们采用近期估计：仅凭软件改进，训练算力效率大约每 4.5 个月翻一番 [79]；推理算力效率的增长可能更快 [80]。为避免对 8.5 次翻倍做几何级数和的近似，我们改为计算 9 次翻倍的几何和，此时增长率提高已超过十倍。由此得出：约 4.5 个月 $\\times,(1-0.76^{9})/(1-0.76)\\approx 17$ 个月（约 1.5 年）后，增长率将提高十倍以上。届时进步速度是今天的十倍，按今天速度需要一年的进步只需约五周。</p><h3 id="关于研究投入回报的不确定性" tabindex="-1">关于研究投入回报的不确定性 <a class="header-anchor" href="#关于研究投入回报的不确定性" aria-label="Permalink to &quot;关于研究投入回报的不确定性&quot;">​</a></h3><p>若干因素可能使 $r$ 的真实取值偏离现有估计。首先，如上所述，尚不清楚哪种软件质量度量最合适。推理效率与自动化研发队伍的规模对应得最直接，而训练效率的提升如何折算成研究者的有效数量并不清楚。然而，现有的 AI 研发 $r$ 估计使用的是训练效率，两种度量下研究投入回报有多相似不得而知。此外，对研究投入回报的恰当评估应同时纳入推理效率与训练效率两方面的改进，而非只取其一。开发一种同时刻画两者并适当权衡的软件质量度量，值得进一步研究。</p><p>现有的 $r$ 估计来自算力快速扩张的时期，软件进步与算力扩张的贡献被混在一起。由于这两类投入在历史上同步增长，把观察到的进步归因于软件改进的估计，实际上可能捕捉到的是由算力增长驱动（或只有在算力增长下才可能）的收益。有些软件改进依赖于规模：例如，Transformer 架构在训练算力很大时带来巨大性能收益，在低算力下收益相对较小 [81]。这种混淆会使 $r$ 的估计偏高：在算力固定或缓慢增长的体制下，$r$ 会低于历史数据所显示的水平。</p><p>另一些因素则意味着更高的 $r$。大多数 $r$ 估计忽略了预训练之外的改进，如后训练或更好的工具调用脚手架 [35]。此外，能力提升还可能以&quot;研究者有效数量&quot;这一指标无法捕捉的方式发挥作用：数量极其庞大的平庸研究者，未必能替代一位天才研究者。若是如此，能力提升对有效研发劳动力的扩张会超过上文线性假设的含义。算力瓶颈也可能被绕开，例如通过对小规模实验更好的外推、软件进步降低实验成本、转向更少依赖算力的方法，以及无需实验的算法进步 [7]。</p><p>$r$ 的估计还依赖并不完美的研发劳动力代理变量，这可能使估计向任一方向偏移。例如，Ho 与 Whitfill [28] 用某领域发表论文的独立作者数来代理研发劳动力。领域划得过窄会因排除同样驱动进步的相邻领域而低估劳动力；划得过宽则会高估。除非被排除的相邻领域的劳动力增速与被纳入领域相同，这种脱节将导致 $r$ 的误算。</p><p>最后，相关数学模型未必能推广到极其庞大的研发劳动力 [82]。历史上，这些模型是在每年几个百分点的增长率下验证的，远低于智能爆炸可能产生的两位数甚至更高的增长率。它们在极限情形下也会失效：模型意味着无限劳动力在有限时间内产生无限进步。但现实约束使这一结果不可能：有些问题必须按顺序解决，物理硬件的运行速度也有上限。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ol><li>机器学习会议通常设有主会轨道和若干研讨会（workshop）轨道。需注意，研讨会轨道的评审标准可能略低于主会轨道。</li><li>根据 METR 的任务时长（time-horizon）指标 [17, 83]，AI 系统能完成的任务长度最初大约每 7 个月翻一番，自 2024 年起加速到约每 3 个月翻一番。沿这一近期趋势外推，到 2028 年年中，AI 系统将能完成需要人类专家投入数月时间的任务，这已落在许多 AI 研发项目的时长范围之内。另见 Kokotajlo 等 [84]。</li><li>Cottier 等 [80] 发现，要让 LLM 达到给定的能力里程碑（如在某个数学基准上达到 GPT-4 级表现），其运行成本每年大约下降 9 至 900 倍，具体取决于能力里程碑。这一成本下降部分来自硬件改进（降低了单位计算的成本），但相当大一部分归因于软件改进。</li><li>在某一技术领域，$r$ 刻画研发投入的增加与所关注的产出变化之间的关系，例如前沿消费级硬件在单位不变价格下可完成的计算量。在 Bloom 等 [27] 中，投入以研发支出（美元）衡量，因此同时包括劳动力与实物资本的增加。而在本文中，我们只考虑劳动力的增加，因为我们关注的是算力存量大致保持不变时软件驱动反馈回路的潜力。这意味着 $r$ 的取值低于把所有投入（即劳动力、数据与算力）都考虑在内的情形。</li><li>$r$ 最终必然会降到 1 以下，因为 AI 进步终将触及计算与物理极限。在到达这些极限之前还能取得多大进步，尚不确定。</li><li>三个 90% 置信区间分别为（0.727 至 2.094）、（0.380 至 2.708）与（1.069 至 3.212）。</li><li>在该分析中，算法效率的改进本身并不能化解这一潜在瓶颈，因为它们会按同样比例同时提高研发与训练的效率。</li><li>具体而言，该论文给出了在何种条件下，自动化研究劳动力（以及经济产出等其他量）会在有限时间内增长到无穷大。</li><li>关于研发各轮次之间的时间间隔如何影响智能爆炸动力学的理论讨论，见 Ord [85]。</li><li>Cunningham 等 [37] 的分析聚焦于自持加速（self-sustaining acceleration）：&quot;当 AI 系统足以在不依赖任何外生投入（人类劳动力、训练算力等）增长的情况下加速 AI 能力进步时。&quot;就本文意义上的软件驱动智能爆炸而言，自持加速是必要条件。</li><li>这类系统可能在某些领域（如某些科学研究领域）是超人类的，而在其他领域（如操纵物理世界中的物体）则不是。</li><li>不过，即便在网络领域，人类的组织流程仍可能给防御方带来额外阻力 [86]。</li><li>另见 Anthropic [87]、英国 AI 安全研究所 [88]、OpenAI [89] 以及 Bogdan 等 [90]。</li><li>例如参见 Tessler 等 [91]。更具推测性的是，AI 系统或许还能加速脑机接口的开发，使人类能够更快地思考和协调。</li><li>如何精确地对智能爆炸进行操作化定义颇为棘手，仍有待后续研究。</li><li>例如，AI 已经在辅助芯片设计 [92]。AI 系统还可能加速机器人技术，从而实现芯片生产流程的自动化。</li></ol><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><p>共 92 条，从略。完整列表见<a href="https://casp.ac/__l5e/assets-v1/5efd4b41-deb5-4513-a0a3-b4f82d2b79ea/intelligence-explosion.pdf" target="_blank" rel="noreferrer">原文 PDF</a> 第 9–12 页。正文引用的几个关键来源：</p><ul><li>[1] I. J. Good, &quot;Speculations concerning the first ultraintelligent machine,&quot; 1966 —— &quot;智能爆炸&quot;概念的最早源头。</li><li>[27] Bloom, Jones, Van Reenen &amp; Webb, &quot;Are ideas getting harder to find?&quot; <em>American Economic Review</em>, 2020 —— 收益递减与&quot;研究投入回报&quot;框架的出处。</li><li>[28] Ho &amp; Whitfill, <em>The software intelligence explosion debate needs experiments</em>, 2025 —— 正文 $r\\in[1.2, 1.9]$ 估计的来源。</li><li>[33] Davidson, Halperin, Houlden &amp; Korinek, <em>When does automating AI research produce explosive growth?</em>, 2026。</li><li>[37] Cunningham 等, <em>The economics of recursive self-improvement</em>, 2026。</li><li>[43] Greenblatt, Cotra &amp; van der Wijk, <em>Brief independent investigation of the OpenAI / Hugging Face hacking incident</em>, METR &amp; Redwood Research, 2026 —— 正文&quot;Hugging Face 事件&quot;的独立调查报告。</li></ul>',90)])])}const c=e(i,[["render",n]]);export{h as __pageData,c as default};
